// Proxy receipt vectors generated by the Go proxy
// (proxy/internal/receipts/sdk_vectors_test.go keeps the file in step with
// the proxy's encoding).
import { describe, it, expect } from "vitest";
import { readFileSync } from "fs";
import { resolve } from "path";
import {
  verifyReceipt,
  computeReceiptDigest,
  portableReceiptFromJSON,
  receiptKeyId,
  __receiptInternals,
} from "../verify";
import type { PortableReceipt } from "../verify";

interface Vector {
  name: string;
  valid: boolean;
  why: string;
  line: string;
  version: number;
  canonical_hex: string;
  digest: string;
}

const file = JSON.parse(readFileSync(resolve(__dirname, "../../../testdata/receipts_v2.json"), "utf8")) as {
  public_key: string;
  key_id: string;
  vectors: Vector[];
};
const PUB = file.public_key;
const byName = (n: string) => {
  const v = file.vectors.find((x) => x.name === n);
  if (!v) throw new Error(`no vector ${n}`);
  return v;
};

describe("proxy receipt vectors", () => {
  it("cover the required cases", () => {
    for (const n of ["v1_allow", "v2_attempt", "v2_outcome_reasons_approver", "v2_tampered_approver", "v2_signed_sig_v1"]) {
      byName(n);
    }
  });

  it("key id matches Go", () => {
    expect(receiptKeyId(PUB)).toBe(file.key_id);
  });

  for (const vec of file.vectors) {
    it(`${vec.name}: valid=${vec.valid}`, () => {
      const r = portableReceiptFromJSON(vec.line);
      expect(verifyReceipt(r, PUB), vec.why).toBe(vec.valid);
      expect(__receiptInternals.receiptVersion(r)).toBe(vec.version);
      const payload =
        vec.version === 2
          ? __receiptInternals.receiptCanonicalV2(r)
          : Buffer.from(__receiptInternals.receiptCanonicalV1(r), "utf8");
      expect(payload.toString("hex")).toBe(vec.canonical_hex);
      expect(computeReceiptDigest(r)).toBe(vec.digest);
    });
  }

  for (const vec of file.vectors.filter((v) => v.valid)) {
    it(`${vec.name}: any field change breaks it`, () => {
      const r = portableReceiptFromJSON(vec.line);
      for (const [k, val] of Object.entries(r)) {
        if (k === "signature" || k === "v") continue;
        let changed: unknown;
        if (Array.isArray(val)) changed = [...val, "x"];
        else if (typeof val === "number") changed = val + 1;
        else if (k === "timestamp") changed = (val as string).endsWith("Z") ? (val as string).replace("Z", "+00:01") : (val as string).slice(0, -6) + "Z";
        else changed = (val as string) + "x";
        expect(verifyReceipt({ ...r, [k]: changed } as PortableReceipt, PUB), k).toBe(false);
      }
    });
  }

  it("unicode, astral characters and empty values are in the vectors", () => {
    const r = portableReceiptFromJSON(byName("v2_outcome_reasons_approver").line);
    expect(r.reasons).toContain("");
    expect(/[\u{10000}-\u{10FFFF}]/u.test((r.reasons ?? []).join(""))).toBe(true);
    expect(r.respBytes).toBe(-1);
  });

  it("timestamp nanoseconds match Go UnixNano", () => {
    const f = __receiptInternals.rfc3339ToUnixNano;
    expect(f("2026-01-02T08:34:07.000000001+05:30")).toBe(f("2026-01-02T03:04:07.000000001Z"));
    expect(f("2026-01-02T03:04:07.5Z")).toBe(1767323047500000000n);
  });

  it("refuses v2 fields on a sig_v1 receipt even when the v1 signature is good", () => {
    const base = portableReceiptFromJSON(byName("v1_allow").line);
    expect(verifyReceipt(base, PUB)).toBe(true);
    const extras: Partial<PortableReceipt>[] = [
      { v: 2 }, { rule: "r" }, { kid: file.key_id }, { reasons: ["a"] }, { reqBytes: 1 }, { respBytes: -1 }, { approver: "a" },
    ];
    for (const e of extras) {
      expect(verifyReceipt({ ...base, ...e }, PUB), JSON.stringify(e)).toBe(false);
    }
  });

  it("portableReceiptFromJSON rejects unknown keys", () => {
    const obj = JSON.parse(file.vectors[0].line);
    obj.extra = 1;
    expect(() => portableReceiptFromJSON(obj)).toThrow();
  });

  it("refuses a lone surrogate (which would encode like U+FFFD)", () => {
    const r = portableReceiptFromJSON(byName("v2_attempt").line);
    expect(verifyReceipt({ ...r, rule: "\uD800" }, PUB)).toBe(false);
  });
});
